pub struct AnalyzeBookUseCase {
    uow_factory: Box<dyn AnalyzeBookUnitOfWorkFactoryTrait>,
    dto: AnalyzeBookDto,
}

impl AnalyzeBookUseCase {
    pub fn new(
        uow_factory: Box<dyn AnalyzeBookUnitOfWorkFactoryTrait>,
        dto: &AnalyzeBookDto,
    ) -> Self {
        AnalyzeBookUseCase {
            uow_factory,
            dto: dto.clone(),
        }
    }
}

impl LongOperation for AnalyzeBookUseCase {
    type Output = BookAnalysisResultDto;

    fn execute(
        &self,
        progress_callback: Box<dyn Fn(OperationProgress) + Send>,
        cancel_flag: Arc<AtomicBool>,
    ) -> Result<Self::Output> {
        use std::sync::atomic::Ordering;

        progress_callback(OperationProgress::new(0.0, Some("Starting...".to_string())));

        let uow = self.uow_factory.create();
        uow.begin_transaction()?;
        let analysed = run_analysis(uow.as_ref(), &self.dto, &*progress_callback, &cancel_flag);
        if cancel_flag.load(Ordering::Relaxed) {
            uow.end_transaction()?;
            return Err(anyhow!("Operation was cancelled"));
        }
        uow.end_transaction()?;
        let (work_id, dto) = analysed?;

        uow.publish_analyze_book_event(vec![work_id], None);
        progress_callback(OperationProgress::new(100.0, Some("completed".to_string())));
        Ok(dto)
    }
}

/// One scene's text, gathered once and reused by every measure.
struct Scene {
    item_id: EntityId,
    title: String,
    /// The chapter this scene sits under, for grouping rows.
    ///
    /// Empty when there is none — a scene directly under a Part, or under the Book itself.
    /// Note that a flat `Item/ChapterScene` *is* its own chapter, so this equals `title`
    /// there; a reader grouping by it should suppress the grouping when the two match
    /// rather than drawing a heading above a single row repeating it.
    chapter_title: String,
    prose: String,
    locale: Option<String>,
}

/// The prose a scene's own text lives in.
fn is_scene_prose(role: &ContentRole) -> bool {
    matches!(role, ContentRole::SceneText)
}

fn run_analysis(
    uow: &dyn AnalyzeBookUnitOfWorkTrait,
    dto: &AnalyzeBookDto,
    progress: &(dyn Fn(OperationProgress) + Send),
    cancel: &AtomicBool,
) -> Result<(EntityId, BookAnalysisResultDto)> {
    use std::sync::atomic::Ordering;

    let g = gather(uow, dto.work_id as EntityId, progress, cancel)?;
    let work_id = g.work.id;

    // The project's house quote style. Resolved once, here, and threaded into every scene's
    // dialogue markers below. A missing row means "never configured", which is exactly what
    // `LocaleDefault` says — so the absence needs no special case, and measurement falls back
    // to the locale table just as insertion does.
    let quote_style: QuoteStyle = uow
        .get_smart_punctuation(&g.work.smart_punctuation)?
        .map(|sp: SmartPunctuation| sp.quote_style)
        .unwrap_or_default();

    let metas = skribisto_compiler::item_metas(&g);
    let scope_id = dto.scope_item_id as EntityId;

    // The container we are mounted on decides how far the subtree runs: a Book's scope ends
    // at the next Book, a Part's at the next Part, and so on.
    let head = metas
        .iter()
        .position(|m| m.id == scope_id)
        .ok_or_else(|| anyhow!("scope item {scope_id} is not in this work's stream"))?;
    let level = compile::StreamLevel::for_container(&metas[head].role, &metas[head].sub_role)
        .unwrap_or(StreamLevel::Book);

    // `row_indices_in`, not `row_indices`: this walk holds the **whole work's** stream,
    // which is binder-major and concatenated with nothing between one binder and the next,
    // while only manuscript rows carry book markers. The bare-slice version cannot see
    // that edge, so a Book's extent ran straight out of the manuscript and swallowed the
    // notes and research binders, and every measure here is a comparison of the book
    // against itself. It only ever stopped because every shipped template ends its
    // manuscript with an explicit `BookEnd`, which is an accident of the templates rather
    // than a rule, and exactly the thing a writer keeping an old draft in another binder
    // would be relying on.
    let rows = compile::row_indices_in(&metas, head, level);

    // Only the rows actually in scope are copied out of the gathered tree. Cloning every
    // item in the work would mean copying every scene's Djot text — the whole manuscript —
    // to analyse one container, and this view is mounted per open tab, so the scope can be
    // far smaller than the book.
    let in_scope: std::collections::HashSet<EntityId> =
        rows.iter().map(|&idx| metas[idx].id).collect();
    // Titles for the whole stream, not just the scope's prose rows: a scene's enclosing
    // chapter head is not itself a prose row, so it is absent from `by_id` below.
    let mut items_titles: HashMap<EntityId, String> = HashMap::new();
    let mut by_id: HashMap<EntityId, (BinderItem, Vec<Content>)> = HashMap::new();
    for b in &g.binders {
        for iwc in &b.items {
            items_titles.insert(iwc.item.id, iwc.item.title.clone());
            if in_scope.contains(&iwc.item.id) {
                by_id.insert(iwc.item.id, (iwc.item.clone(), iwc.contents.clone()));
            }
        }
    }

    // Per-item language, for the sentence splitter and the dialogue convention. The house
    // resolver, already used by search, word count and the mention scan.
    let scope_items: Vec<BinderItem> = by_id.values().map(|(item, _)| item.clone()).collect();
    let mut lang: HashMap<EntityId, Vec<String>> = HashMap::new();
    language::tags_in_binder(&g.work.dict_language, &scope_items, &mut lang);

    // ── phase 1: pull each scene's text out once ──
    let mut scenes: Vec<Scene> = Vec::new();
    for &idx in &rows {
        if cancel.load(Ordering::Relaxed) {
            return Err(anyhow!("Operation was cancelled"));
        }
        let meta = &metas[idx];
        if !meta.activated {
            continue;
        }
        // `row_indices` answers the *stream view*'s question — what gets a row in Full Book —
        // which legitimately includes Part and Chapter headings as structural markers. They
        // are not scenes: per `COMBINATIONS` a Part owns a title and a synopsis but never
        // `SceneText`, so admitting one here produces a phantom zero-word scene that drags
        // the word-count median down and is then reported as a scene whose prose does not
        // match its synopsis — when it has no prose to match. `counts_prose` is the
        // narrower predicate that means "owns a SceneText body", and is the same one word
        // counting keys off, so the two cannot disagree about what a scene is.
        if !skribisto_model::counts_prose(&meta.role, &meta.sub_role) {
            continue;
        }
        let Some((item, contents)) = by_id.get(&meta.id) else {
            continue;
        };

        let take = |want: fn(&ContentRole) -> bool| -> String {
            contents
                .iter()
                .filter(|c| c.activated && want(&c.role))
                .map(|c| djot_to_plain_text(&c.data, &DjotImportOptions::default()))
                .collect::<Vec<_>>()
                .join("\n\n")
        };

        let chapter_title = compile::enclosing_head(&metas, idx, StreamLevel::Chapter)
            .and_then(|h| items_titles.get(&metas[h].id).cloned())
            .unwrap_or_default();

        scenes.push(Scene {
            item_id: meta.id,
            title: item.title.clone(),
            chapter_title,
            prose: take(is_scene_prose),
            locale: language::primary(lang.get(&meta.id).map(Vec::as_slice).unwrap_or_default())
                .to_string()
                .into(),
        });
    }
    progress(OperationProgress::new(
        40.0,
        Some("Measuring...".to_string()),
    ));

    // ── phase 2: per-scene measures ──
    //
    // Each scene stands alone: `prose_stats::measure` reads one string and returns numbers
    // about that string. Nothing here accumulates across scenes, which is what keeps the
    // pass linear — and why the cancel check is the only per-scene bookkeeping left.
    let mut scene_rows: Vec<SceneAnalysis> = Vec::with_capacity(scenes.len());
    let mut total_words: u64 = 0;

    for s in &scenes {
        if cancel.load(Ordering::Relaxed) {
            return Err(anyhow!("Operation was cancelled"));
        }
        // The house quote style is per project, not per scene, so it is resolved once above
        // the loop and handed to every scene's markers. A scene's *locale* still varies —
        // a manuscript is not monolingual — which is why the two are separate arguments.
        let markers =
            prose_stats::markers_for(s.locale.as_deref().unwrap_or(""), quote_style.clone());
        let stats = prose_stats::measure(&s.prose, s.locale.as_deref(), markers);
        total_words += stats.words as u64;

        scene_rows.push(SceneAnalysis::Measured {
            item_id: s.item_id,
            title: s.title.clone(),
            chapter_title: s.chapter_title.clone(),
            words: stats.words as i64,
            sentence_mean: stats.mean_sentence_words(),
            sentence_stddev: stats.sentence_words_stddev(),
            paragraph_mean: stats.mean_paragraph_words(),
            punctuation_per_1k: stats.punctuation_per_1k,
            dialogue: stats.dialogue,
        });
    }

    Ok((
        work_id,
        BookAnalysisResultDto {
            scene: SceneAnalysis::Empty,
            scenes: SceneAnalyses::Measured(scene_rows),
            total_words,
        },
    ))
}
